parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "name": {
      "type": ["string", "null"],
      "description": "Extracted contact/lead name (e.g. Rahul) or null if missing"
    },
    "company": {
      "type": ["string", "null"],
      "description": "Extracted company name or industry/domain (e.g. Finance company) or null if missing"
    },
    "budget": {
      "type": ["number", "null"],
      "description": "Numeric budget integer value in INR (e.g. 1500000 for 15 lakh)"
    },
    "timeline": {
      "type": ["string", "null"],
      "description": "Extracted timeline, urgency, or support duration (e.g. '2 weeks (Start immediately)', 'Support for 2 years', or 'Not specified')"
    },
    "requirement": {
      "type": ["string", "null"],
      "description": "Concise summary of project requirements"
    },
    "lead_score": {
      "type": "number",
      "description": "Qualification score between 0 and 100"
    },
    "lead_quality": {
      "type": "string",
      "enum": ["Hot", "Warm", "Cold"]
    },
    "priority": {
      "type": "string",
      "enum": ["P1", "P2", "P3"],
      "description": "P1 for Hot leads (>=80), P2 for Warm (50-79), P3 for Cold (<50)"
    },
    "reason": {
      "type": "string",
      "description": "Brief explanation of why this score and priority were assigned"
    },
    "recommended_action": {
      "type": "string",
      "enum": ["CALL IMMEDIATELY", "SCHEDULE MEETING", "SEND PROPOSAL", "FOLLOW UP", "REQUEST MORE INFO"]
    }
  },
  "required": ["lead_score", "lead_quality", "priority", "reason", "recommended_action"]
}

parameters.text:
